15	
16	/// Tela 4 — Meus Registros, spec-4-1's real build: every `Entry`,
17	/// newest-first, grouped by day, each card marked by origin. Replaces the
18	/// former `MeusRegistrosPlaceholderScreen`.
19	///
20	/// [cubit] is a DI `lazySingleton` (Code Map) — this `StatefulWidget` never
21	/// closes it (`BlocProvider.value`, same convention
22	/// `AccountSettingsScreen` already uses for its own singleton cubit); only
23	/// this screen's own [ScrollController] is this `State`'s to dispose.
24	///
25	/// The global `ExpiryOverlayHost` shows its "Sessão expirada" dialog via
26	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
27	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
28	/// rebuilt from scratch underneath it, so [_scrollController]'s position
29	/// and [cubit]'s state survive that overlay appearing with no extra code
30	/// needed here (Acceptance Criteria's third bullet).
31	class MeusRegistrosScreen extends StatefulWidget {
32	  const MeusRegistrosScreen({required this.cubit, super.key});
33	
34	  final MeusRegistrosCubit cubit;
35	
36	  @override
37	  State<MeusRegistrosScreen> createState() => _MeusRegistrosScreenState();
38	}
39	
40	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
41	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
42	  // `BootSplashScreen`.
43	  static const _skeletonThreshold = Duration(milliseconds: 300);
44	
45	  final ScrollController _scrollController = ScrollController();
46	  Timer? _skeletonTimer;
47	  bool _showSkeleton = false;
48	
49	  @override
50	  void initState() {
51	    super.initState();
52	    widget.cubit.loadFirstPage();
53	    _skeletonTimer = Timer(_skeletonThreshold, () {
54	      if (mounted) {
55	        setState(() => _showSkeleton = true);
56	      }
57	    });
58	    _scrollController.addListener(_onScroll);
59	  }
60	
61	  @override
62	  void dispose() {
63	    _skeletonTimer?.cancel();
64	    _scrollController
65	      ..removeListener(_onScroll)
66	      ..dispose();
67	    super.dispose();
68	  }
69	
70	  void _onScroll() {
71	    if (!_scrollController.hasClients) {
72	      return;
73	    }
74	    final position = _scrollController.position;
75	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
76	    // purely as a scroll-distance buffer, not a new literal) for a
77	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
78	    // there's no further page or a call is already in flight.
79	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
80	      widget.cubit.loadMore();
81	    }
82	  }
83	
84	  @override
85	  Widget build(BuildContext context) {
86	    return BlocProvider.value(
87	      value: widget.cubit,
88	      child: Scaffold(
89	        backgroundColor: DesignTokens.colorSurfaceBg,
90	        body: Column(
91	          children: [
92	            const BackArrowHeader(title: 'Meus Registros'),
93	            Expanded(
94	              child: BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
95	                builder: (context, state) => switch (state) {
96	                  MeusRegistrosLoading() =>
97	                    _showSkeleton
98	                        ? const _SkeletonList()
99	                        : const SizedBox.shrink(),
100	                  MeusRegistrosEmpty() => const _EmptyState(),
101	                  MeusRegistrosError(message: final message) => _ErrorState(
102	                    message: message,
103	                    onRetry: widget.cubit.loadFirstPage,
104	                  ),
105	                  MeusRegistrosLoaded() => _EntryList(
106	                    state: state,
107	                    scrollController: _scrollController,
108	                    onRetryLoadMore: widget.cubit.retryLoadMore,
109	                    onRetryTap: (entry) => widget.cubit.retry(entry.id),
110	                  ),
111	                },
112	              ),
113	            ),
114	          ],
115	        ),
116	      ),
117	    );
118	  }
119	}
120	
121	class _SkeletonList extends StatelessWidget {
122	  const _SkeletonList();
123	
124	  // Not a real count of anything server-sent — just enough placeholder
125	  // cards to fill a typical screen while the first page is in flight.
126	  static const _placeholderCount = 4;
127	
128	  @override
129	  Widget build(BuildContext context) {
130	    return ListView.builder(
131	      padding: DesignTokens.screenPadding,
132	      itemCount: _placeholderCount,
133	      itemBuilder: (context, index) => Padding(
134	        padding: const EdgeInsets.only(bottom: DesignTokens.spacingSm),
135	        child: const EntrySkeletonCard(),
136	      ),
137	    );
138	  }
139	}
140	
141	class _EmptyState extends StatelessWidget {
142	  const _EmptyState();
143	
144	  @override
145	  Widget build(BuildContext context) {
146	    // Boundaries: "polished empty-state CTA (4.3) — plain 'no entries yet'
147	    // text only" this story.
148	    return Center(
149	      child: Text(
150	        'Nenhum registro ainda.',
151	        style: DesignTokens.textBodyMd.copyWith(
152	          color: DesignTokens.colorTextSecondary,
153	        ),
154	      ),
155	    );
156	  }
157	}
158	
159	class _ErrorState extends StatelessWidget {
160	  const _ErrorState({required this.message, required this.onRetry});
161	
162	  final String message;
163	  final VoidCallback onRetry;
164	
165	  @override
166	  Widget build(BuildContext context) {
167	    return Center(
168	      child: Padding(
169	        padding: DesignTokens.screenPadding,
170	        child: Column(
171	          mainAxisSize: MainAxisSize.min,
172	          children: [
173	            Text(
174	              message,
175	              textAlign: TextAlign.center,
176	              style: DesignTokens.textBodyMd.copyWith(
177	                color: DesignTokens.colorTextPrimary,
178	              ),
179	            ),
180	            const SizedBox(height: DesignTokens.spacingMd),
181	            TextButton(
182	              onPressed: onRetry,
183	              child: Text(
184	                'Tentar novamente',
185	                style: DesignTokens.textLabelMd.copyWith(
186	                  color: DesignTokens.colorPrimary,
187	                ),
188	              ),
189	            ),
190	          ],
191	        ),
192	      ),
193	    );
194	  }
195	}
196	
197	class _EntryList extends StatelessWidget {
198	  const _EntryList({
199	    required this.state,
200	    required this.scrollController,
201	    required this.onRetryLoadMore,
202	    required this.onRetryTap,
203	  });
204	
205	  final MeusRegistrosLoaded state;
206	  final ScrollController scrollController;
207	  final VoidCallback onRetryLoadMore;
208	  final void Function(Entry entry) onRetryTap;
209	
210	  @override
211	  Widget build(BuildContext context) {
212	    final groups = state.groups;
213	    // A non-empty `state.entries` can still yield zero groups if every one
214	    // of its `occurredAt` values is malformed (`groupEntriesByDate()` skips
215	    // rather than throws) — fall back to the same plain empty-state text
216	    // rather than rendering a ListView with nothing visibly in it.
217	    if (groups.isEmpty) {
218	      return const _EmptyState();
219	    }
220	    return ListView.builder(
221	      controller: scrollController,
222	      padding: DesignTokens.screenPadding,
223	      itemCount: groups.length + 1,
224	      itemBuilder: (context, index) {
225	        if (index == groups.length) {
226	          return _LoadMoreFooter(
227	            hasMore: state.nextCursor != null,
228	            isLoading: state.isLoadingMore,
229	            failed: state.loadMoreFailed,
230	            onRetry: onRetryLoadMore,
231	          );
232	        }
233	        return _DateGroupSection(
234	          group: groups[index],
235	          badgeFor: state.badgeFor,
236	          onRetryTap: onRetryTap,
237	        );
238	      },
239	    );
240	  }
241	}
242	
243	class _DateGroupSection extends StatelessWidget {
244	  const _DateGroupSection({
245	    required this.group,
246	    required this.badgeFor,
247	    required this.onRetryTap,
248	  });
249	
250	  final EntryDateGroup group;
251	
