68	Map<String, dynamic> _entryJson({
69	  required String id,
70	  required String content,
71	  required String source,
72	  required String occurredAt,
73	}) => {
74	  'id': id,
75	  'content': content,
76	  'source': source,
77	  'chatMessageId': null,
78	  'occurredAt': occurredAt,
79	  'serverRevision': 1,
80	  'createdAt': occurredAt,
81	  'updatedAt': occurredAt,
82	};
