84	/// End-to-end coverage for spec-4-2's pending-write lifecycle — the
85	/// counterpart `entries_list_flow_e2e_test.dart` already proves for
86	/// spec-4-1's `list()` path. Driven directly against the exact
87	/// `sl<PendingEntryWriteTracker>()`/`sl<MeusRegistrosCubit>()` singleton
88	/// instances `entries_injection.dart` wires to share one real
89	/// `EntriesRepositoryImpl` -> `EntriesRemoteDataSource` -> `ApiClient` ->
90	/// `Dio` (both real interceptors attached) -> a real `entries` Hive box —
91	/// exactly how a capture cubit's `create()`/the badge's `retry()` reach
92	/// `MeusRegistrosCubit` in the running app.
93	///
94	/// This complements rather than duplicates existing coverage:
95	/// `pending_entry_write_tracker_test.dart`/`meus_registros_cubit_test.dart`/
96	/// `meus_registros_screen_test.dart` already prove the tracker and the
97	/// cubit/UI wiring against fakes. None of them drives a `create()` ->
98	/// retryable-failure -> manual-`retry()` -> confirmation sequence through
99	/// the real `RetryInterceptor` + real transport together.
100	void main() {
101	  TestWidgetsFlutterBinding.ensureInitialized();
102	
103	  const secureStorageChannel = MethodChannel(
104	    'plugins.it_nomads.com/flutter_secure_storage',
105	  );
106	  final fakeNativeStorage = <String, String>{};
107	
108	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
109	    final args = call.arguments as Map<dynamic, dynamic>;
110	    switch (call.method) {
111	      case 'write':
112	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
113	        return null;
114	      case 'read':
115	        return fakeNativeStorage[args['key'] as String];
116	      case 'delete':
117	        fakeNativeStorage.remove(args['key'] as String);
118	        return null;
119	      case 'containsKey':
120	        return fakeNativeStorage.containsKey(args['key'] as String);
121	      default:
122	        return null;
123	    }
124	  }
125	
126	  late FakePathProviderPlatform fakePathProvider;
127	  late _FakeHttpClientAdapter adapter;
128	
129	  setUp(() async {
130	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
131	        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
132	    fakePathProvider = FakePathProviderPlatform();
133	    PathProviderPlatform.instance = fakePathProvider;
134	
135	    await resetCoreDependencies();
136	    await setupCoreDependencies();
137	
138	    adapter = _FakeHttpClientAdapter();
139	    sl<Dio>().httpClientAdapter = adapter;
140	
141	    // `entries-create` is a bearer-required operation — seed a user access
142	    // token through the real `AccessTokenProvider` (backed by the faked
143	    // secure storage channel above) so the real header interceptor has one
144	    // to send.
145	    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
146	  });
147	
148	  tearDown(() async {
149	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
150	        .setMockMethodCallHandler(secureStorageChannel, null);
151	    fakeNativeStorage.clear();
152	    await Hive.close();
153	    await resetCoreDependencies();
154	    await fakePathProvider.cleanUp();
155	  });
