159	    'persists the confirmed entry to the real Hive box, and the real '
160	    "MeusRegistrosCubit (sharing the tracker) prepends it into its loaded "
161	    'state via confirmedWrites',
162	    () async {
163	      // Starts the real MeusRegistrosCubit subscribing to the shared
164	      // tracker's streams before the write is created, same as the running
165	      // app does ("Meus Registros" mounts and subscribes for its whole
166	      // lifetime regardless of which screen started the capture).
167	      final cubit = sl<MeusRegistrosCubit>();
168	      adapter.queueJsonResponse(200, {
169	        'data': <Map<String, dynamic>>[],
170	        'meta': {'nextCursor': null},
171	      });
172	      await cubit.loadFirstPage();
173	      expect(cubit.state, isA<MeusRegistrosEmpty>());
174	
175	      adapter.queueJsonResponse(200, {
