195	      expect(result.isRight(), isTrue);
196	      final loaded = cubit.state as MeusRegistrosLoaded;
197	      expect(loaded.entries.map((e) => e.id), ['entry-1']);
198	      expect(loaded.pendingWrites, isEmpty);
199	
200	      // Exactly one real request left through the fake transport, built by
201	      // the real UrlBuilder/HeaderInterceptor, not a mock of ApiClient.
202	      final createRequest = adapter.requests.last;
203	      expect(createRequest.path, sl<UrlBuilder>().build('entries-create'));
204	      expect(createRequest.data, {
205	        'content': 'Primeiro registro do dia.',
